function loadCharacter() {
    if (!THREE.GLTFLoader) {
        console.warn('Scene3D: GLTFLoader missing; cannot load character.');
        return;
    }
    const loader = new THREE.GLTFLoader();
    loader.load(
        '/assets/KayKit Character Animations 1.2/Animations/gltf/KayKit_AnimatedCharacter_v1.2.glb',
        gltf => {
            characterGroup = gltf.scene;
            characterGroup.traverse(node => {
                if (node.isMesh) {
                    node.castShadow = true;
                    node.receiveShadow = true;
                }
            });
            // Character soll mit Füßen AUF dem Boden stehen (Y=0)
            adjustToGround(characterGroup);
            scene.add(characterGroup);

            // 🎬 Initialisiere Animations-System
            if (window.CharacterAnimations) {
                window.CharacterAnimations.init(characterGroup, gltf);
                console.log('🎬 Animations verfügbar:', window.CharacterAnimations.listAnimations());
            }

            attachStaffToCharacter();
            characterReady = true;
            console.log('✅ Animated Character geladen mit Animationen!');
        },
        undefined,
        error => {
            console.warn('Scene3D: failed to load character model', error);
        }
    );
}

