}

enum MessageMode {
  NORMAL,     // Bleibt für immer (wie WhatsApp)
  SNAPCHAT,   // Einmal lesen, dann weg
  TIMED       // Auto-Delete nach X Zeit
}
```

### UI-Implementierung

```dart
class ChatScreen extends StatefulWidget {
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Row(
          children: [
            Text('⬢ NAJIKA'),
