async function updateInventoryPanel() {
    const content = document.getElementById('inventory-content');
    if (!content) return;

    // Lade Status vom Server
    try {
        const response = await fetch('/api/status');
        const data = await response.json();
        window.currentStatus = data;  // Speichern für andere Funktionen

        const inv = data.user?.inventory || [];

        if (inv.length === 0) {
            content.innerHTML = '<p style="color: #888; text-align: center; padding: 20px;">Inventar leer</p>';
            return;
        }

    let html = '<div style="display: grid; gap: 10px;">';
    inv.forEach(item => {
        html += `
            <div style="background: rgba(102, 126, 234, 0.1); border: 2px solid rgba(102, 126, 234, 0.3); border-radius: 8px; padding: 10px; display: flex; justify-content: space-between; align-items: center;">
                <div>
                    <div style="font-weight: bold; color: #667eea;">${item.name || 'Item'}</div>
                    <div style="font-size: 12px; color: #aaa;">${item.type || 'Misc'}</div>
                </div>
                <div style="background: rgba(118, 75, 162, 0.3); padding: 5px 10px; border-radius: 5px; font-weight: bold;">
                    x${item.quantity || 1}
                </div>
            </div>
        `;
    });
    html += '</div>';
    content.innerHTML = html;
}

