                    </div>
                `;
            });
            html += '</div>';
        }

        content.innerHTML = html;
    } catch (error) {
        content.innerHTML = '<p style="color: #e74c3c; text-align: center; padding: 20px;">❌ Fehler beim Laden</p>';
        console.error('Failed to load skills:', error);
    }
}

