   164→        // === DUNGEON PROPS als Gegner (Creative!) ===
   165→        barrel_mimic: {
   166→            name: 'Fass-Mimik',
   167→            model: 'KayKit_DungeonRemastered_1.1_FREE/KayKit_DungeonRemastered_1.1_FREE/Assets/gltf/barrel.gltf',
   168→            hp: 25,
   169→            damage: 8,
