   171→            attackRange: 1.5,
   172→            scale: 2.0,
   173→            xp: 12,
   174→            loot: ['barrel_wood', 'mystery_item'],
   175→            color: 0x996633,
   176→            tier: 2,
   177→            surprise: true // Looks like normal prop!
   178→        },
   179→        crate_golem: {
   180→            name: 'Kisten-Golem',
   181→            model: 'KayKit_DungeonRemastered_1.1_FREE/KayKit_DungeonRemastered_1.1_FREE/Assets/gltf/crate_small_A.gltf',
   182→            hp: 35,
   183→            damage: 6,
   184→            speed: 0.5,
   185→            attackRange: 2.0,
   186→            scale: 2.5,
   187→            xp: 15,
   188→            loot: ['wooden_plank', 'nails'],
   189→            color: 0x886644,
   190→            tier: 2
   191→        }
   192→    };
   193→
   194→    // Enemy AI States
   195→    const AI_STATE = {
   196→        IDLE: 'idle',
   197→        PATROL: 'patrol',
   198→        CHASE: 'chase',
   199→        ATTACK: 'attack',
   200→        HURT: 'hurt',
   201→        DEAD: 'dead'
   202→    };
   203→
   204→    // Active enemies in scene
   205→    let activeEnemies = [];
   206→
   207→    // Animation mixer for all enemies
   208→    let enemyMixers = [];
   209→    const clock = new THREE.Clock();
   210→
   211→    /**
   212→     * Enemy Class
   213→     */
   214→    class Enemy {
   215→        constructor(type, position, level = 1, scene) {
   216→            this.type = type;
   217→            this.data = ENEMY_TYPES[type];
   218→            this.level = level;
   219→            this.scene = scene;
   220→
   221→            // Stats (skaliert mit Level)
   222→            this.maxHp = Math.floor(this.data.hp * (1 + level * 0.3));
   223→            this.hp = this.maxHp;
   224→            this.damage = Math.floor(this.data.damage * (1 + level * 0.2));
   225→            this.speed = this.data.speed;
   226→            this.attackRange = this.data.attackRange;
   227→            this.xp = Math.floor(this.data.xp * (1 + level * 0.5));
   228→
   229→            // Position & Movement
   230→            this.position = new THREE.Vector3(...position);
   231→            this.rotation = Math.random() * Math.PI * 2;
   232→            this.velocity = new THREE.Vector3();
   233→            this.target = null; // Player or patrol point
   234→
   235→            // AI State
   236→            this.state = AI_STATE.IDLE;
   237→            this.stateTimer = 0;
   238→            this.patrolPoints = this.generatePatrolPoints(position);
   239→            this.currentPatrolIndex = 0;
   240→            this.attackCooldown = 0;
   241→
   242→            // 3D Objects
   243→            this.group = null;
   244→            this.model = null;
   245→            this.healthBar = null;
   246→            this.mixer = null;
   247→            this.animations = {};
   248→
   249→            // Flags
   250→            this.isDead = false;
   251→            this.isLoaded = false;
   252→        }
   253→
   254→        async load() {
   255→            try {
   256→                // Load model via KayKitLoader
   257→                const modelPath = this.data.model;
   258→                const gltf = await this.loadGLTF('/assets/' + modelPath);
   259→
   260→                this.group = new THREE.Group();
   261→                this.model = gltf.scene.clone();
   262→                this.model.scale.setScalar(this.data.scale);
   263→
   264→                // Add subtle glow effect
   265→                this.model.traverse(child => {
   266→                    if (child.isMesh) {
   267→                        child.castShadow = true;
   268→                        child.receiveShadow = true;
   269→                        // Emissive glow für Skelette
   270→                        if (child.material) {
   271→                            child.material = child.material.clone();
   272→                            child.material.emissive = new THREE.Color(this.data.color);
   273→                            child.material.emissiveIntensity = 0.2;
   274→                        }
   275→                    }
   276→                });
   277→
   278→                this.group.add(this.model);
   279→                this.group.position.copy(this.position);
   280→                this.group.rotation.y = this.rotation;
   281→
   282→                // Health Bar
   283→                this.createHealthBar();
   284→
   285→                // Animations (wenn vorhanden)
   286→                if (gltf.animations && gltf.animations.length > 0) {
   287→                    this.mixer = new THREE.AnimationMixer(this.model);
   288→                    enemyMixers.push(this.mixer);
   289→
   290→                    gltf.animations.forEach(clip => {
   291→                        this.animations[clip.name] = this.mixer.clipAction(clip);
   292→                    });
   293→
   294→                    // Play idle animation
   295→                    if (this.animations['Idle']) {
   296→                        this.animations['Idle'].play();
   297→                    }
   298→                }
   299→
   300→                this.scene.add(this.group);
   301→                this.isLoaded = true;
   302→
   303→                console.log(`✅ Enemy loaded: ${this.data.name} (Lv ${this.level})`);
   304→            } catch (error) {
   305→                console.error('❌ Enemy load failed:', error);
   306→            }
   307→        }
   308→
   309→        loadGLTF(url) {
   310→            return new Promise((resolve, reject) => {
   311→                const loader = new THREE.GLTFLoader();
   312→                loader.load(url, resolve, undefined, reject);
   313→            });
   314→        }
   315→
   316→        createHealthBar() {
   317→            // Simple 3D health bar above enemy
   318→            const barWidth = 2;
   319→            const barHeight = 0.2;
   320→
   321→            const barGeometry = new THREE.PlaneGeometry(barWidth, barHeight);
   322→            const barMaterial = new THREE.MeshBasicMaterial({
   323→                color: 0x00ff00,
   324→                side: THREE.DoubleSide
   325→            });
   326→
   327→            this.healthBar = new THREE.Mesh(barGeometry, barMaterial);
   328→            this.healthBar.position.y = 3; // Above model
   329→            this.healthBar.renderOrder = 999; // Always on top
   330→
   331→            this.group.add(this.healthBar);
   332→        }
   333→
   334→        updateHealthBar() {
   335→            if (!this.healthBar) return;
   336→
   337→            const healthPercent = Math.max(0, this.hp / this.maxHp);
   338→
   339→            // Color: Green -> Yellow -> Red
   340→            let color;
   341→            if (healthPercent > 0.5) {
   342→                color = new THREE.Color(0x00ff00); // Green
   343→            } else if (healthPercent > 0.2) {
   344→                color = new THREE.Color(0xffff00); // Yellow
   345→            } else {
   346→                color = new THREE.Color(0xff0000); // Red
   347→            }
   348→
   349→            this.healthBar.material.color = color;
   350→            this.healthBar.scale.x = healthPercent;
   351→        }
   352→
   353→        generatePatrolPoints(center) {
   354→            // Generate 3-5 random patrol points around spawn
   355→            const points = [];
   356→            const count = 3 + Math.floor(Math.random() * 3);
   357→            const radius = 5;
   358→
   359→            for (let i = 0; i < count; i++) {
   360→                const angle = (i / count) * Math.PI * 2;
   361→                const x = center[0] + Math.cos(angle) * radius;
   362→                const z = center[2] + Math.sin(angle) * radius;
   363→                points.push(new THREE.Vector3(x, 0, z));
   364→            }
   365→
   366→            return points;
   367→        }
   368→
   369→        update(delta, playerPosition) {
   370→            if (this.isDead || !this.isLoaded) return;
   371→
   372→            this.stateTimer += delta;
   373→            this.attackCooldown = Math.max(0, this.attackCooldown - delta);
   374→
   375→            // Update AI based on state
   376→            switch (this.state) {
   377→                case AI_STATE.IDLE:
   378→                    this.updateIdle(delta);
   379→                    break;
   380→                case AI_STATE.PATROL:
   381→                    this.updatePatrol(delta);
   382→                    break;
   383→                case AI_STATE.CHASE:
   384→                    this.updateChase(delta, playerPosition);
   385→                    break;
   386→                case AI_STATE.ATTACK:
   387→                    this.updateAttack(delta, playerPosition);
   388→                    break;
   389→            }
   390→
   391→            // Check if player in range -> chase
   392→            if (playerPosition && this.state !== AI_STATE.ATTACK) {
   393→                const distToPlayer = this.position.distanceTo(playerPosition);
   394→                if (distToPlayer < 15) { // Aggro range
   395→                    this.state = AI_STATE.CHASE;
   396→                }
   397→            }
   398→
   399→            // Apply velocity
   400→            this.position.add(this.velocity);
   401→            this.group.position.copy(this.position);
   402→            this.group.rotation.y = this.rotation;
   403→
   404→            // Billboard health bar towards camera
   405→            if (this.healthBar && window.Scene3D && Scene3D.camera) {
   406→                this.healthBar.lookAt(Scene3D.camera.position);
   407→            }
   408→        }
   409→
   410→        updateIdle(delta) {
   411→            this.velocity.set(0, 0, 0);
   412→
   413→            // Nach 2-5 Sekunden -> Patrol
   414→            if (this.stateTimer > 2 + Math.random() * 3) {
   415→                this.state = AI_STATE.PATROL;
   416→                this.stateTimer = 0;
   417→            }
   418→        }
   419→
   420→        updatePatrol(delta) {
   421→            const target = this.patrolPoints[this.currentPatrolIndex];
   422→            const direction = target.clone().sub(this.position);
   423→            const distance = direction.length();
   424→
   425→            if (distance < 0.5) {
   426→                // Reached patrol point -> next
   427→                this.currentPatrolIndex = (this.currentPatrolIndex + 1) % this.patrolPoints.length;
   428→                this.state = AI_STATE.IDLE;
   429→                this.stateTimer = 0;
   430→            } else {
   431→                // Move towards patrol point
   432→                direction.normalize();
   433→                this.velocity.set(direction.x * this.speed * delta, 0, direction.z * this.speed * delta);
   434→                this.rotation = Math.atan2(direction.x, direction.z);
   435→            }
   436→        }
   437→
   438→        updateChase(delta, playerPosition) {
   439→            if (!playerPosition) {
   440→                this.state = AI_STATE.PATROL;
   441→                return;
   442→            }
   443→
   444→            const direction = playerPosition.clone().sub(this.position);
   445→            const distance = direction.length();
   446→
   447→            if (distance > 20) {
   448→                // Player zu weit -> zurück zu Patrol
   449→                this.state = AI_STATE.PATROL;
   450→                this.stateTimer = 0;
   451→            } else if (distance < this.attackRange) {
   452→                // In Attack Range -> Attack
   453→                this.state = AI_STATE.ATTACK;
   454→                this.stateTimer = 0;
   455→                this.velocity.set(0, 0, 0);
   456→            } else {
   457→                // Chase player
   458→                direction.normalize();
   459→                this.velocity.set(direction.x * this.speed * delta * 2, 0, direction.z * this.speed * delta * 2);
   460→                this.rotation = Math.atan2(direction.x, direction.z);
   461→            }
   462→        }
   463→
   464→        updateAttack(delta, playerPosition) {
   465→            if (!playerPosition) {
   466→                this.state = AI_STATE.CHASE;
   467→                return;
   468→            }
   469→
   470→            const distance = this.position.distanceTo(playerPosition);
   471→
   472→            if (distance > this.attackRange * 1.5) {
   473→                // Player escaped -> chase
   474→                this.state = AI_STATE.CHASE;
   475→            } else {
   476→                // Face player
   477→                const direction = playerPosition.clone().sub(this.position);
   478→                this.rotation = Math.atan2(direction.x, direction.z);
   479→
   480→                // Attack every 1-2 seconds
   481→                if (this.attackCooldown <= 0) {
   482→                    this.performAttack(playerPosition);
   483→                    this.attackCooldown = 1 + Math.random();
   484→                }
   485→            }
   486→        }
   487→
   488→        performAttack(playerPosition) {
   489→            console.log(`⚔️ ${this.data.name} attacks! Damage: ${this.damage}`);
   490→
   491→            // TODO: Damage player via API
   492→            // For now: Visual feedback
   493→            if (this.animations['Attack']) {
   494→                this.animations['Attack'].reset().play();
   495→            }
   496→
   497→            // Trigger damage event
   498→            if (typeof window.onEnemyAttack === 'function') {
   499→                window.onEnemyAttack(this.damage, this.position);
   500→            }
   501→        }
   502→
   503→        takeDamage(amount) {
   504→            if (this.isDead) return;
   505→
   506→            this.hp = Math.max(0, this.hp - amount);
   507→            this.updateHealthBar();
   508→
   509→            console.log(`💥 ${this.data.name} took ${amount} damage! HP: ${this.hp}/${this.maxHp}`);
   510→
   511→            if (this.hp <= 0) {
   512→                this.die();
   513→            } else {
   514→                // Play hurt animation
   515→                if (this.animations['Hit']) {
   516→                    this.animations['Hit'].reset().play();
   517→                }
   518→                this.state = AI_STATE.HURT;
   519→                setTimeout(() => {
   520→                    if (!this.isDead) this.state = AI_STATE.CHASE;
   521→                }, 500);
   522→            }
   523→        }
   524→
   525→        die() {
   526→            this.isDead = true;
   527→            this.state = AI_STATE.DEAD;
   528→
   529→            console.log(`💀 ${this.data.name} defeated! +${this.xp} XP`);
   530→
   531→            // Play death animation
   532→            if (this.animations['Death']) {
   533→                this.animations['Death'].reset().play();
   534→            }
   535→
   536→            // Fade out and remove
   537→            setTimeout(() => {
   538→                if (this.group) {
   539→                    this.scene.remove(this.group);
   540→                    const index = activeEnemies.indexOf(this);
   541→                    if (index > -1) activeEnemies.splice(index, 1);
   542→                }
   543→            }, 2000);
   544→
   545→            // Drop loot
   546→            this.dropLoot();
   547→
   548→            // Trigger death event
   549→            if (typeof window.onEnemyKilled === 'function') {
   550→                window.onEnemyKilled(this.xp, this.data.loot, this.position);
   551→            }
   552→        }
   553→
   554→        dropLoot() {
   555→            // TODO: Spawn loot items in 3D scene
   556→            console.log(`💎 Loot dropped:`, this.data.loot);
   557→        }
   558→
   559→        dispose() {
   560→            if (this.group) {
   561→                this.scene.remove(this.group);
   562→            }
   563→            if (this.mixer) {
   564→                const index = enemyMixers.indexOf(this.mixer);
   565→                if (index > -1) enemyMixers.splice(index, 1);
   566→            }
   567→        }
   568→    }
   569→
   570→    /**
   571→     * Wählt Enemy-Typ basierend auf Dungeon-Level & Schwierigkeit
   572→     */
   573→    function getEnemyTypeForLevel(level) {
   574→        const tier = Math.ceil(level / 3); // Level 1-3 = Tier 1, 4-6 = Tier 2, etc.
   575→
   576→        // Pool von Enemies nach Tier
   577→        const tierPools = {
   578→            1: ['skeleton_warrior', 'skeleton_archer', 'haunted_pumpkin'],
   579→            2: ['skeleton_mage', 'skeleton_tank', 'skeleton_axe', 'barrel_mimic', 'crate_golem'],
   580→            3: ['corrupted_knight', 'corrupted_rogue'],
   581→            4: ['corrupted_barbarian', 'dark_sorcerer']
   582→        };
   583→
   584→        const pool = tierPools[Math.min(tier, 4)] || tierPools[1];
   585→        return pool[Math.floor(Math.random() * pool.length)];
   586→    }
   587→
   588→    /**
   589→     * Spawn enemies from dungeon data - ERWEITERT!
   590→     */
   591→    function spawnEnemies(dungeon, scene) {
   592→        if (!dungeon || !dungeon.enemies) return;
   593→
   594→        console.log(`🧟 Spawning ${dungeon.enemies.length} enemies (Level ${dungeon.level})...`);
   595→
   596→        dungeon.enemies.forEach((enemyData, index) => {
   597→            // Intelligente Enemy-Auswahl basierend auf Level
   598→            let enemyType;
   599→
   600→            if (dungeon.level <= 2) {
   601→                // Early levels: Nur Skelette & Pumpkins
   602→                const earlyPool = ['skeleton_warrior', 'skeleton_archer', 'haunted_pumpkin'];
   603→                enemyType = earlyPool[index % earlyPool.length];
   604→            } else if (dungeon.level <= 5) {
   605→                // Mid levels: Skelette + Mimics
   606→                const midPool = ['skeleton_mage', 'skeleton_tank', 'skeleton_axe', 'barrel_mimic', 'crate_golem'];
   607→                enemyType = midPool[index % midPool.length];
   608→            } else if (dungeon.level <= 8) {
   609→                // High levels: Corrupted Heroes
   610→                const highPool = ['corrupted_knight', 'corrupted_rogue', 'skeleton_mage', 'skeleton_axe'];
   611→                enemyType = highPool[index % highPool.length];
   612→            } else {
   613→                // End-game: Bosses & Elite
   614→                const bossPool = ['corrupted_barbarian', 'dark_sorcerer', 'corrupted_knight'];
   615→                enemyType = bossPool[index % bossPool.length];
   616→            }
   617→
   618→            // Fallback: Generic mapping
   619→            if (!ENEMY_TYPES[enemyType]) {
   620→                enemyType = getEnemyTypeForLevel(dungeon.level);
   621→            }
   622→
   623→            const enemy = new Enemy(enemyType, enemyData.position, enemyData.level || dungeon.level, scene);
   624→            enemy.load();
   625→            activeEnemies.push(enemy);
   626→        });
   627→    }
   628→
   629→    /**
   630→     * Update all active enemies
   631→     */
   632→    function updateEnemies(playerPosition) {
   633→        const delta = clock.getDelta();
   634→
   635→        // Update animation mixers
   636→        enemyMixers.forEach(mixer => {
   637→            mixer.update(delta);
   638→        });
   639→
   640→        // Update each enemy AI
   641→        activeEnemies.forEach(enemy => {
   642→            enemy.update(delta, playerPosition);
   643→        });
   644→    }
   645→
   646→    /**
   647→     * Clear all enemies (on room change)
   648→     */
   649→    function clearAllEnemies() {
   650→        activeEnemies.forEach(enemy => enemy.dispose());
   651→        activeEnemies = [];
   652→        enemyMixers = [];
   653→        console.log('🧹 All enemies cleared');
   654→    }
   655→
   656→    /**
   657→     * Damage nearest enemy (player attack)
   658→     */
   659→    function damageNearestEnemy(playerPosition, damage, range = 3) {
   660→        if (!playerPosition) return null;
   661→
   662→        let nearest = null;
   663→        let nearestDist = Infinity;
   664→
   665→        activeEnemies.forEach(enemy => {
   666→            if (enemy.isDead) return;
   667→            const dist = enemy.position.distanceTo(playerPosition);
   668→            if (dist < range && dist < nearestDist) {
   669→                nearest = enemy;
   670→                nearestDist = dist;
   671→            }
   672→        });
   673→
   674→        if (nearest) {
   675→            nearest.takeDamage(damage);
   676→            return nearest;
   677→        }
   678→
   679→        return null;
   680→    }
   681→
   682→    /**
   683→     * Get all living enemies
   684→     */
   685→    function getLivingEnemies() {
   686→        return activeEnemies.filter(e => !e.isDead);
   687→    }
   688→
   689→    // Public API
   690→    window.DungeonEnemies = {
   691→        spawnEnemies,
   692→        updateEnemies,
   693→        clearAllEnemies,
   694→        damageNearestEnemy,
   695→        getLivingEnemies,
   696→        Enemy,
   697→        ENEMY_TYPES,
   698→        AI_STATE
   699→    };
   700→
   701→    console.log('🧟 Dungeon Enemy System initialized');
   702→})();
