def drink_najika():
    """Trinken erhöht Durst"""
    update_needs()
    n = STATE["najika"]

    n["thirst"] = min(100, n["thirst"] + 35)  # Thirst increases faster than hunger
    n["happiness"] = min(100, n["happiness"] + 3)
    n["last_drink"] = time.time()

    # Add Wasser to inventory if not there
    user = STATE["user"]
